void tach_update( UInt16 val )
{
 	#define REF_RPM    (dei_feature_get( DEI_FEAT_RPM_REF_DIV10 ) * 10)

	set_rpm_data(val);
	
	if( (dei_feature_get( DEI_FEAT_TACH_VAL_LEARNED ) == 2) && (dei_feature_get( DEI_FEAT_CONTROL_DOOR_LOCK_OPTION ) == 3) && (val > (REF_RPM + (0.3*REF_RPM))) )
	{
      cmd_q_insert(INPUT_RPM_CONTROL_LOCK, COMMAND_INSERT_TIMEOUT );      
	}
	
	#undef RPM
}
